window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q15"]=window.__LIBQ["the-gioi-hoan-my"]["q15"]||{};window.__LIBQ["the-gioi-hoan-my"]["q15"]["techniques"]={"updatedAt":"2026-07-26","count":47,"techniques":[{"id":"lieu-than-phap-tram-tien","name":"Liễu Thần pháp trảm tiên","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Pháp môn","phamCap":"","hePhai":"Liễu Thần pháp","soHuu":["Thạch Hạo"],"blurb":"Pháp môn do Liễu Thần truyền lại, có thể hóa thành nhiều trật tự thần liên để trói buộc mục tiêu.","detail":"Thạch Hạo thi triển pháp môn này trong lúc luyện hóa thần mang. Các trật tự thần liên từ sau lưng hắn đâm ra, quấn lấy thần mang và phối hợp với những pháp môn khác để trấn áp.","thuocTinh":"Trật tự thần liên","nguonGoc":"Liễu Thần","congNang":["Hóa thành nhiều trật tự thần liên để trói buộc và luyện hóa thần mang."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1412","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1412","loai":"thi triển","importance":"normal","giaiDoan":"Trấn áp thần mang","text":"Thạch Hạo hóa ra nhiều trật tự thần liên để quấn trói và luyện hóa thần mang.","anchor":"Liễu Thần phương pháp trảm Tiên, rất nhiều trật tự thần liên đâm ra, về phía trước lan tràn, khốn trói buộc này thần mang, tiến hành luyện hóa."}]},"capNhatToi":"@c1412","nguon":["@c1412"]},{"id":"lot-xac-tu-chi","name":"Lột xác tứ chi","cn":"","loai":"luyen-the","loaiLabel":"Phương pháp luyện thể","phamCap":"Chưa xác định","hePhai":"Thể tu","soHuu":["Thạch Hạo"],"blurb":"Ý tưởng tu luyện do Thạch Hạo đề ra sau khi ngón trỏ trái hoàn thành niết bàn. Phương pháp hướng tới lột xác toàn bộ tứ chi để chống đỡ Tứ Cực và tăng sức chiến đấu.","detail":"Thạch Hạo dự định dùng mô hình dung hợp Tiên huyết với thần mang trảm tiên để rèn luyện các chi còn lại. Phương pháp mới dừng ở giai đoạn khởi ý, chưa được triển khai toàn diện.","thuocTinh":"Luyện thể và lột xác tứ chi","nguonGoc":"Do Thạch Hạo suy diễn từ quá trình niết bàn ngón trỏ trái","yeuCau":"Tái hiện quá trình lột xác tương tự ngón trỏ trái","uyLuc":"Hướng tới phát huy sức chiến đấu mạnh nhất của Tứ Cực","dacDiem":"Lấy tứ chi làm nền tảng chống đỡ khai thiên địa Tứ Cực","chieuTieuBieu":[],"cacTang":[],"trangThai":"Mới khởi ý","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1413","tangDatToi":"Khởi ý","trangThai":"Chưa hoàn thành"}],"congNang":["Lột xác tứ chi theo mô hình niết bàn của ngón trỏ trái để tăng sức chiến đấu."],"capNhatToi":"@c1413","tabs":{"tienTrinh":[{"chuong":"@c1413","loai":"xuất hiện","importance":"normal","giaiDoan":"Khởi ý","text":"Thạch Hạo đề ra hướng lột xác toàn bộ tứ chi để chống đỡ Tứ Cực và phát huy sức chiến đấu mạnh nhất.","anchor":"tứ chi thông thiên, chống đỡ khai thiên địa Tứ Cực, có thể phát huy ra mạnh nhất sức chiến đấu"}]},"nguon":["@c1413"]},{"id":"phong-ngu-to-thuat-cua-bich-nhan-kim-lan-su-toc","name":"Phòng ngự tổ thuật của Bích Nhãn Kim Lân Sư tộc","cn":"","loai":"bi-thuat","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Bích Nhãn Kim Lân Sư tộc","soHuu":["Em trai Bích Nhãn Kim Lân Sư Vương"],"blurb":"Tổ thuật phòng ngự của Bích Nhãn Kim Lân Sư tộc, được em trai Sư Vương vận dụng để bảo vệ thân thể.","detail":"Em trai Bích Nhãn Kim Lân Sư Vương thi triển tổ thuật này khi chống lại Thạch Hạo, nhưng lớp phòng ngự bị đao chớp giật công phá.","thuocTinh":"Phòng ngự","congNang":["Tạo khả năng phòng thân cho người thi triển."],"nguoiTu":[{"ten":"Em trai Bích Nhãn Kim Lân Sư Vương","tuChuong":"@c1414","tangDatToi":"Không rõ","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1414","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển phòng thân","text":"Em trai Bích Nhãn Kim Lân Sư Vương vận dụng tổ thuật phòng ngự nhưng bị đao chớp giật của Thạch Hạo công phá.","anchor":"công phá sư tử phòng ngự tổ thuật, cũng chém xuống nó nửa cái đầu lâu"}]},"capNhatToi":"@c1414","nguon":["@c1414"]},{"id":"lac-loi","name":"Lạc lối","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật đồng thuật","phamCap":"Không rõ","hePhai":"Bích Nhãn Kim Lân Sư tộc","soHuu":["Bích Nhãn Kim Lân Sư Vương"],"blurb":"Đồng thuật dùng đôi mắt xanh để cầm cố thần hồn và hấp thu nguyên thần của mục tiêu.","detail":"Bích Nhãn Kim Lân Sư Vương từng dựa vào thuật này để vượt cảnh giới giết địch. Khi dùng với Thạch Hạo, nó khiến xương trán hắn đau và nguyên thần cứng lại trong khoảnh khắc trước khi hắn khôi phục.","thuocTinh":"Nguyên thần","uyLuc":"Có khả năng cầm cố thần hồn, hấp thu nguyên thần và từng được dùng để vượt cảnh giới giết địch.","dacDiem":"Hiệu lực thông qua đôi mắt xanh của người thi triển.","chieuTieuBieu":["Cầm cố và hấp thu nguyên thần"],"congNang":["Cầm cố thần hồn và kéo nguyên thần của mục tiêu vào trong mắt."],"nguoiTu":[{"ten":"Bích Nhãn Kim Lân Sư Vương","tuChuong":"@c1415","tangDatToi":"Có thể thi triển trong thực chiến","trangThai":"Đã thi triển"}],"trangThai":"Người thi triển đã tử trận","capNhatToi":"@c1415","tabs":{"tienTrinh":[{"chuong":"@c1415","loai":"thi triển","importance":"normal","giaiDoan":"Vận dụng thực chiến","text":"Bích Nhãn Kim Lân Sư Vương dùng Lạc lối làm nguyên thần Thạch Hạo cứng lại trong khoảnh khắc nhưng không thể hấp thu nguyên thần của hắn.","anchor":"phải đem người Nguyên Thần nuốt vào đi"}]},"nguon":["@c1415"]},{"id":"bat-diet-kinh","name":"Bất Diệt Kinh","cn":"","aliases":["Bất Diệt kinh văn"],"loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Công pháp được Thạch Hạo vận chuyển tới cực hạn khi giao chiến với cường giả Trảm Ngã cảnh.","detail":"Áo nghĩa của Bất Diệt Kinh khi được vận chuyển tới cực hạn giúp chiến lực của Thạch Hạo tăng mạnh.","thuocTinh":"Tăng cường chiến lực","uyLuc":"Giúp Thạch Hạo đánh nổ bàn tay của một cường giả Trảm Ngã cảnh trong một đòn chính diện.","congNang":["Tăng mạnh chiến lực khi áo nghĩa được vận chuyển tới cực hạn."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1416","tangDatToi":"Vận chuyển áo nghĩa tới cực hạn","trangThai":"đang tu luyện"}],"capNhatToi":"@c1416","tabs":{"tienTrinh":[{"chuong":"@c1416","loai":"thi triển","importance":"normal","giaiDoan":"Áo nghĩa vận chuyển tới cực hạn","text":"Thạch Hạo vận chuyển áo nghĩa Bất Diệt Kinh tới cực hạn, khiến chiến lực tăng mạnh khi cứu hai chiến binh Đế quan.","anchor":"Bất Diệt kinh văn áo nghĩa bị vận chuyển tới cực hạn, chiến lực bạo tăng"}]},"nguon":["@c1416"]},{"id":"bat-huu-thien-dao","name":"Bất hủ thiên đao","cn":"","loai":"than-thong","loaiLabel":"Sát sinh đại thuật","phamCap":"","hePhai":"Dị vực","soHuu":["Vũ Phong"],"blurb":"Sát sinh đại thuật do một tồn tại bất hủ truyền cho Vũ Phong, cho phép biến cánh tay thành thiên đao khổng lồ để chém địch.","detail":"Khi thi triển toàn lực, cánh tay phải của Vũ Phong hóa thành thiên đao dài hàng vạn trượng. Pháp môn này được mô tả là truyền thừa tương ứng với Tiên Đạo pháp môn phía Đế Quan.","thuocTinh":"Sát sinh","nguonGoc":"Do một tồn tại bất hủ truyền thụ.","uyLuc":"Có thể biến cánh tay thành thiên đao khổng lồ để công kích đối thủ.","dacDiem":"Thiên đao được tạo trực tiếp từ cánh tay người thi triển.","chieuTieuBieu":["Bất hủ thiên đao"],"congNang":["Biến cánh tay phải thành thiên đao dài hàng vạn trượng để chém địch."],"nguoiTu":[{"ten":"Vũ Phong","tuChuong":"@c1417","tangDatToi":"Thi triển toàn lực","trangThai":"Đã tử trận"}],"trangThai":"Được Vũ Phong thi triển","capNhatToi":"@c1417","tabs":{"tienTrinh":[{"chuong":"@c1417","loai":"thi triển","importance":"normal","giaiDoan":"Đối quyết Thạch Hạo","text":"Vũ Phong biến cánh tay phải thành thiên đao khổng lồ và thi triển toàn lực để đối đầu Thạch Hạo.","anchor":"Đây là bất hủ truyền cho hắn, được xưng bất hủ thiên đao, có thể chém phá tất cả địch!"}]},"nguon":["@c1417"]},{"id":"loi-de-phap","name":"Lôi Đế pháp","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"Lôi Đế","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật được Thạch Hạo dung hợp vào quyền ấn cùng Luân Hồi thần thông và Liễu Thần thuật.","detail":"Trong trận quyết đấu với Vũ Phong, Thạch Hạo ẩn Lôi Đế pháp trong tay phải để tăng uy lực cho quyền ấn mà không công khai nguồn gốc chiêu thức.","thuocTinh":"Lôi","uyLuc":"Được dung hợp vào quyền ấn tuyệt sát của Thạch Hạo.","dacDiem":"Có thể phối hợp với nhiều bảo thuật khác trong cùng một quyền ấn.","congNang":["Dung hợp vào quyền ấn để tăng sức công phạt."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1417","tangDatToi":"Có thể dung hợp vào quyền ấn","trangThai":"Đang tu luyện"}],"trangThai":"Được Thạch Hạo sử dụng","capNhatToi":"@c1417","tabs":{"tienTrinh":[{"chuong":"@c1417","loai":"thi triển","importance":"normal","giaiDoan":"Dung hợp quyền ấn","text":"Thạch Hạo ẩn Lôi Đế pháp cùng Luân Hồi thần thông và Liễu Thần thuật trong tay phải để tung quyền ấn.","anchor":"Lôi Đế pháp, Luân Hồi thần thông, Liễu Thần thuật các loại, toàn bộ ẩn chứa ở trên tay phải của hắn"}]},"nguon":["@c1417"]},{"id":"lieu-than-thuat","name":"Liễu Thần thuật","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"Liễu Thần","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật được Thạch Hạo bí mật dung hợp với Lôi Đế pháp và Luân Hồi thần thông trong quyền ấn quyết chiến.","detail":"Thạch Hạo ẩn Liễu Thần thuật trong tay phải thay vì công khai thi triển những bảo thuật dễ làm lộ thân phận.","thuocTinh":"","uyLuc":"Được dung hợp vào quyền ấn tuyệt sát của Thạch Hạo.","dacDiem":"Có thể phối hợp với nhiều bảo thuật khác mà không bộc lộ riêng biệt.","congNang":["Dung hợp vào quyền ấn để tăng sức công phạt."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1417","tangDatToi":"Có thể dung hợp vào quyền ấn","trangThai":"Đang tu luyện"}],"trangThai":"Được Thạch Hạo sử dụng","capNhatToi":"@c1417","tabs":{"tienTrinh":[{"chuong":"@c1417","loai":"thi triển","importance":"normal","giaiDoan":"Dung hợp quyền ấn","text":"Thạch Hạo bí mật dung hợp Liễu Thần thuật với Lôi Đế pháp và Luân Hồi thần thông trong đòn quyết chiến.","anchor":"Lôi Đế pháp, Luân Hồi thần thông, Liễu Thần thuật các loại, toàn bộ ẩn chứa ở trên tay phải của hắn"}]},"nguon":["@c1417"]},{"id":"truong-vuc-ky-di-duoi-long-dat","name":"Trường vực kỳ dị dưới lòng đất","cn":"","loai":"khac","loaiLabel":"Trường vực","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":[],"blurb":"Trường vực nằm dưới lòng đất trong Thần Dược Sơn Mạch, tạo ra lực hạn chế tốc độ của sinh linh xâm nhập.","detail":"Khi Thạch Hạo độn xuống lòng đất để tránh thủ lĩnh ma cầm, trường vực này làm tốc độ của hắn giảm mạnh và khiến đối phương nhanh chóng đuổi kịp.","thuocTinh":"Hạn chế tốc độ","congNang":["Tạo lực trường lớn dưới lòng đất, làm giảm tốc độ của người đi vào."],"dacDiem":"Ẩn trong một khu vực ngầm của Thần Dược Sơn Mạch.","capNhatToi":"@c1420","dinhDanh":"goc","nguon":["@c1420"]},{"id":"trang-vuc-van-veo-thoi-khong","name":"Tràng vực vặn vẹo thời không","cn":"","loai":"khac","loaiLabel":"Tràng vực","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":[],"blurb":"Tràng vực kỳ dị trong Thần Dược Thần Mạch, có khả năng làm thời không biến dạng.","detail":"Tràng vực đột ngột phát sáng khi Thạch Hạo định áp chế các thần dược, khiến thời không vặn vẹo và thân thể hắn rung mạnh trước lúc Hoàng Kim Ngưu xuất hiện.","thuocTinh":"Thời không","congNang":["Làm thời không xung quanh biến dạng và tác động mạnh lên thân thể sinh linh ở gần."],"tabs":{"tienTrinh":[{"chuong":"@c1421","loai":"xuất hiện","importance":"normal","giaiDoan":"Bị kích hoạt","text":"Tràng vực phát sáng và vặn vẹo thời không khi Thạch Hạo ra tay bắt thần dược.","anchor":"đột nhiên phát sáng, xuất hiện kỳ dị tràng vực, vặn vẹo thời không, để Thạch Hạo thân thể rung bần bật"}]},"capNhatToi":"@c1421","nguon":["@c1421"]},{"id":"to-kiem-tran-9999-kiem-quang","name":"Tổ kiếm trận 9.999 kiếm quang","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm trận","phamCap":"Không rõ","hePhai":"Dị Vực","soHuu":["Đại tu sĩ Độn Nhất hộ tống quần địch"],"blurb":"Kiếm trận phóng ra 9.999 luồng kiếm quang cùng chém vào mục tiêu.","detail":"Đại tu sĩ Độn Nhất dùng toàn bộ kiếm quang chém trúng Hoàng Kim Ngưu, nhưng đòn đánh chỉ làm tóe lửa và không phá được thân thể của nó.","uyLuc":"Có thể liên tiếp phóng ra 9.999 luồng kiếm quang.","nguoiTu":[{"ten":"Đại tu sĩ Độn Nhất hộ tống quần địch","tuChuong":"@c1424","tangDatToi":"Có thể thi triển kiếm trận","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1424","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển trọn kiếm trận","text":"Đại tu sĩ Độn Nhất phóng 9.999 kiếm quang chém trúng Hoàng Kim Ngưu nhưng không làm nó bị thương.","anchor":"liên tiếp bổ ra 9,999 ánh kiếm, toàn bộ chém trúng Hoàng Kim Ngưu"}]},"nguon":["@c1424"]},{"id":"sat-tran-cua-nhom-toc-lam","name":"Sát trận của nhóm tóc lam","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Dị Vực","soHuu":["Sinh linh tóc lam có cánh xanh","Nhóm tu sĩ trẻ Dị vực ngoài Thần Dược Sơn Mạch"],"blurb":"Trận pháp do nhóm tu sĩ Dị Vực chuẩn bị để vây giết Thạch Hạo.","detail":"Nam tử tóc lam cùng đồng bọn dùng pháp khí và trận pháp phong tỏa chiến trường, khiến Thạch Hạo phải cưỡng ép bản nguyên để thi triển Bảo thuật Lôi Đế phá vây.","congNang":["Vây quét và phong tỏa mục tiêu trong chiến trường."],"nguoiTu":[{"ten":"Sinh linh tóc lam có cánh xanh","tuChuong":"@c1424","tangDatToi":"Tham gia bố trí","trangThai":"đã thi triển"},{"ten":"Nhóm tu sĩ trẻ Dị vực ngoài Thần Dược Sơn Mạch","tuChuong":"@c1424","tangDatToi":"Tham gia bố trí","trangThai":"đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1424","loai":"thi triển","importance":"normal","giaiDoan":"Vây giết Thạch Hạo","text":"Nhóm tóc lam chuẩn bị và phát động trận pháp nhằm vây giết Thạch Hạo đang bị thương.","anchor":"Nhóm này người chuẩn bị chính là trận pháp!"}]},"nguon":["@c1424"]},{"id":"mang-nguu-hong-cua-hoang-kim-nguu","name":"Mãng ngưu hống của Hoàng Kim Ngưu","cn":"","loai":"than-thong","loaiLabel":"Thần thông âm ba","phamCap":"Không rõ","hePhai":"Hoàng Kim Ngưu","soHuu":["Hoàng Kim Ngưu"],"blurb":"Thần thông âm ba được Hoàng Kim Ngưu phát động ở cự ly gần.","detail":"Tiếng rống tạo sóng chấn động dữ dội, khiến nhiều tu sĩ trẻ Dị Vực trực tiếp nổ tung và hình thần đều diệt.","uyLuc":"Ở cự ly gần có thể đánh nổ nhiều tu sĩ cùng lúc.","nguoiTu":[{"ten":"Hoàng Kim Ngưu","tuChuong":"@c1424","tangDatToi":"Có thể thi triển ở cự ly gần","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1424","loai":"thi triển","importance":"normal","giaiDoan":"Âm ba cự ly gần","text":"Hoàng Kim Ngưu phát động tiếng rống ở cự ly gần, làm nhiều tu sĩ Dị Vực nổ tung.","anchor":"mãng ngưu hống ở khoảng cách gần như thế bạo phát, dẫn phát mang tính tan nạn hậu quả"}]},"nguon":["@c1424"]},{"id":"thuy-khi","name":"Thủy khí","cn":"","aliases":["Mẫu khí Tiên khí"],"loai":"khac","loaiLabel":"Tiên khí","phamCap":"Không rõ","hePhai":"Tiên đạo","soHuu":["Thạch Hạo"],"blurb":"Đạo Tiên khí đầu tiên của Thạch Hạo từng tan biến rồi tái hiện khi hắn hấp thu Tiên trấp Kim dịch. Đây là mẫu khí có thể lưu lại dấu ấn sinh thành những Tiên khí sau nhưng cũng tiềm ẩn nguy cơ phản phệ chủ nhân.","detail":"Thủy khí xuất hiện dưới dạng một luồng bạch khí cực nhạt ở bụng Thạch Hạo và chủ động hấp thu lực lượng thần bí trong kim dịch. Mạnh Thiên Chính từng giải thích rằng mẫu khí vốn phải rời đi sau khi lưu lại dấu ấn sinh thành các Tiên khí khác; cưỡng ép giữ và bồi dưỡng nó có thể biến nó thành gông xiềng giết chết người tu luyện.","thuocTinh":"Tiên đạo","nguonGoc":"Đạo Tiên khí đầu tiên từng hình thành rồi tan vào cơ thể Thạch Hạo.","uyLuc":"Có thể để lại dấu ấn sinh thành các Tiên khí khác.","dacDiem":"Cưỡng ép lưu giữ và bồi dưỡng có thể khiến thủy khí phản phệ người tu luyện.","trangThai":"Đã hoàn toàn thành hình","capNhatToi":"@c1426","congNang":["Để lại dấu ấn sinh thành các Tiên khí khác.","Hấp thu bí lực Tiên đạo trong Tiên trấp Kim dịch.","Làm mẫu thể sinh thành ba đạo tiên khí.","Cắm rễ tại Luân Hải và bộc phát sức mạnh sau khi hoàn toàn thành hình."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1426","tangDatToi":"Hoàn toàn thành hình","trangThai":"Đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1426","loai":"tái hiện","importance":"major","giaiDoan":"Thủy khí tái hiện","text":"Thủy khí từng tan biến tái hiện trong cơ thể Thạch Hạo, hấp thu bí lực từ Tiên trấp Kim dịch và được hắn quyết định thu nhận bất chấp nguy cơ phản phệ.","anchor":"chắc chắn sẽ trở thành một đầu ghìm chết tự mình gông xiềng"},{"chuong":"@c1427","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Hoàn toàn thành hình","text":"Thạch Hạo hấp thu bí lực trong ao vàng, khiến thủy khí cắm rễ tại Luân Hải và hoàn toàn thành hình.","anchor":"nó đang trở nên chân thực, từ từ lớn mạnh, càng ngày càng trắng noãn, thần bí mà đáng sợ."}]},"nguon":["@c1426","@c1427"]},{"id":"ba-dao-tien-khi-cua-thach-hao","name":"Ba đạo Tiên khí của Thạch Hạo","cn":"","aliases":[],"loai":"khac","loaiLabel":"Tiên khí","phamCap":"Không rõ","hePhai":"Tiên đạo","soHuu":["Thạch Hạo"],"blurb":"Ba đạo Tiên khí trong cơ thể Thạch Hạo bị khí tức Tiên đạo của kim dịch kích thích nên liên tục tụ tán. Khi thủy khí tái hiện, chúng bị đánh tan thành tinh quang rồi chìm vào huyết nhục và xương cốt.","detail":"Trong lúc Thạch Hạo hấp thu bí lực từ ao kim dịch, ba đạo Tiên khí tự động ngưng tụ rồi phân tán nhiều lần. Sau một đợt chấn động, cả ba bị đánh tan và trở lại thân thể dưới dạng vô số điểm sáng.","thuocTinh":"Tiên đạo","dacDiem":"Bị Tiên trấp Kim dịch kích thích tụ tán và bị đánh tan khi thủy khí tái hiện.","trangThai":"Tan vào huyết nhục và xương cốt","capNhatToi":"@c1426","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1426","tangDatToi":"Ba đạo","trangThai":"Bị đánh tan vào thân thể"}],"tabs":{"tienTrinh":[{"chuong":"@c1426","loai":"thi triển","importance":"normal","giaiDoan":"Bị kim dịch kích thích","text":"Ba đạo Tiên khí liên tục tụ tán dưới tác động của khí tức Tiên đạo rồi bị đánh tan thành tinh quang khi thủy khí xuất hiện.","anchor":"ba đạo Tiên khí bị trùng kích tán"}]},"nguon":["@c1426"]},{"id":"ba-doa-dai-dao-chi-hoa","name":"Ba đóa đại đạo chi hoa","cn":"","loai":"khac","loaiLabel":"Dị tượng tu luyện","phamCap":"Đóa thứ hai xuất hiện sinh linh","hePhai":"Tiên khí","soHuu":["Thạch Hạo"],"blurb":"Dị tượng hình thành khi ba đạo tiên khí lao khỏi thiên linh cái của Thạch Hạo. Đóa hoa trung tâm đã xuất hiện một tiểu nhân mơ hồ giữa hỗn độn khí.","detail":"Một đóa hoa vốn đã có tiểu nhân ngồi như tồn tại trong quá khứ. Tại chương này, đóa hoa thứ hai rung động và hiện ra thêm một sinh linh mơ hồ.","thuocTinh":"Đại đạo dị tượng","uyLuc":"Sự xuất hiện của sinh linh trong đóa hoa thứ hai tạo nên một kỳ cảnh chấn động tâm hồn.","dacDiem":"Ba đóa hoa do ba đạo tiên khí hóa thành; hai đóa đã lần lượt xuất hiện tiểu nhân.","congNang":["Biểu hiện biến hóa của ba đạo tiên khí trên thiên linh cái.","Đóa hoa thứ hai có thể hiện ra một tiểu nhân mơ hồ giữa hỗn độn khí."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1427","tangDatToi":"Đóa thứ hai xuất hiện sinh linh","trangThai":"Đang phát triển"}],"trangThai":"Đóa thứ hai đã xuất hiện sinh linh","capNhatToi":"@c1427","tabs":{"tienTrinh":[{"chuong":"@c1427","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Sinh linh trong đóa thứ hai","text":"Đóa đại đạo chi hoa trung tâm rung động, phóng thích hỗn độn khí và hiện ra một tiểu nhân mơ hồ.","anchor":"Một cái tiểu nhân ngồi xếp bằng ở trên, phi thường mơ hồ, nhưng cũng chấn động tâm hồn!"}]},"nguon":["@c1427"]},{"id":"ba-dao-tien-khi","name":"Ba đạo tiên khí","cn":"","loai":"khac","loaiLabel":"Tiên khí tu luyện","phamCap":"Ba đạo hoàn chỉnh","hePhai":"Tiên khí","soHuu":["Thạch Hạo"],"blurb":"Ba đạo tiên khí lưu chuyển trong cơ thể Thạch Hạo, diễn hóa hàm nghĩa tam sinh vạn vật. Chúng lao khỏi thiên linh cái và hóa thành ba đóa đại đạo chi hoa.","detail":"Sau khi thủy khí hoàn toàn thành hình, ba đạo tiên khí xuất hiện rõ ràng, tăng cường sinh cơ rồi diễn hóa thành ba đóa đại đạo chi hoa trên đầu Thạch Hạo.","thuocTinh":"Tiên khí","uyLuc":"Có thể lưu chuyển trong cơ thể, tăng sinh cơ và diễn hóa dị tượng đại đạo.","dacDiem":"Ba đạo tiên khí lấy thủy khí làm mẫu thể và có thể hóa thành ba đóa đại đạo chi hoa.","congNang":["Diễn hóa hàm nghĩa tam sinh vạn vật.","Tăng cường sinh cơ trong cơ thể Thạch Hạo.","Hóa thành ba đóa đại đạo chi hoa trên thiên linh cái."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1427","tangDatToi":"Ba đạo tiên khí lưu chuyển và hóa hoa","trangThai":"Đang tu luyện"}],"trangThai":"Đang lưu chuyển ổn định","capNhatToi":"@c1427","tabs":{"tienTrinh":[{"chuong":"@c1427","loai":"thi triển","importance":"normal","giaiDoan":"Hóa thành đại đạo chi hoa","text":"Ba đạo tiên khí lưu chuyển trong cơ thể Thạch Hạo, diễn hóa hàm nghĩa tam sinh vạn vật rồi bay khỏi thiên linh cái và hóa thành ba đóa hoa.","anchor":"ba đạo tiên khí xuất hiện, ở tại trong cơ thể lưu chuyển, diễn biến tam sinh vạn vật chi hàm nghĩa"}]},"nguon":["@c1427"]},{"id":"tien-co-phap","name":"Tiên Cổ pháp","cn":"","loai":"cong-phap","loaiLabel":"Hệ thống tu luyện","phamCap":"","hePhai":"Tiên Cổ","soHuu":["Thạch Hạo"],"blurb":"Con đường tu luyện được Thạch Hạo chọn làm chủ để chuẩn bị cho bước đột phá tiếp theo.","detail":"Kinh văn Tiên đạo của Tiên Cổ pháp hiện ra trong tâm hải và phủ thành hoa văn trên thân thể Thạch Hạo, phối hợp với bí chất trong cổ trì để bồi dưỡng thể phách, thần hồn và ba đạo Tiên khí.","thuocTinh":"Tiên đạo","uyLuc":"Thúc đẩy ba đạo Tiên khí phân tán và cắm rễ vào thể phách.","dacDiem":"Kinh văn hiện ra cả trong tâm hải lẫn trên thân thể người tu luyện.","congNang":["Bồi dưỡng thể phách, thần hồn và ba đạo Tiên khí.","Giúp Tiên khí phân giải rồi cắm rễ trong ngũ tạng, xương cốt và cốt tủy."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1430","tangDatToi":"Chọn làm con đường chủ tu","trangThai":"đang tu luyện"}],"trangThai":"đang tu luyện","capNhatToi":"@c1430","tabs":{"tienTrinh":[{"chuong":"@c1430","loai":"thi triển","importance":"normal","giaiDoan":"Chọn làm chủ tu","text":"Thạch Hạo lấy Tiên Cổ pháp làm chủ, đọc kinh văn Tiên đạo và dùng bí chất trong cổ trì bồi dưỡng ba đạo Tiên khí.","anchor":"Hiện nay ta chủ tu Tiên Cổ pháp, vậy thì lấy nó làm chủ"}]},"nguon":["@c1430"]},{"id":"tinh-tuy-tram-tien-trat-dao","name":"Tinh túy Trảm Tiên Trát Đao","cn":"","loai":"than-thong","loaiLabel":"Sát thuật","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Sát thuật hóa thành thần mang đỏ sậm, mang uy thế trảm thần giết Tiên.","detail":"Thạch Hạo phát thần mang từ ngón trỏ để giao kích trực tiếp với Thủy khí. Đòn đánh có thể lay động mục tiêu và làm Hoàng Đạo thạch xung quanh rạn nứt nhưng chưa đủ sức chém đứt Thủy khí.","thuocTinh":"Sát phạt","uyLuc":"Có thể lay động Thủy khí và khiến Hoàng Đạo thạch xung quanh rạn nứt.","dacDiem":"Biểu hiện thành thần mang đỏ sậm phát ra từ ngón trỏ.","congNang":["Giao kích trực tiếp và lay động Thủy khí."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1430","tangDatToi":"Có thể phát thần mang đỏ sậm","trangThai":"đang sử dụng"}],"trangThai":"đang được sử dụng","capNhatToi":"@c1430","tabs":{"tienTrinh":[{"chuong":"@c1430","loai":"thi triển","importance":"normal","giaiDoan":"Lay động Thủy khí","text":"Thạch Hạo thi triển tinh túy Trảm Tiên Trát Đao, khiến thần mang đỏ sậm giao kích và lay động Thủy khí nhưng không thể chém đứt nó.","anchor":"Trảm Tiên Trát Đao đạo kia tinh túy lại có thể lay động Thủy khí"}]},"nguon":["@c1430"]},{"id":"con-duong-tu-thanh-tien-khi","name":"Con đường tu thành tiên khí","cn":"","loai":"cong-phap","loaiLabel":"Con đường tu luyện","phamCap":"","hePhai":"Tiên đạo","soHuu":["Thạch Hạo"],"blurb":"Con đường tu luyện Tiên khí của Thạch Hạo bước sang giai đoạn cắm rễ toàn diện trong thể phách.","detail":"Ba đạo Tiên khí không còn chỉ tụ thành những đóa Đại đạo chi hoa không rễ mà phân giải thành vô số sợi nhỏ, dung nhập ngũ tạng, xương cốt và cốt tủy để thúc đẩy quá trình tiến hóa sâu.","thuocTinh":"Tiên khí","uyLuc":"Thúc đẩy ngũ tạng, xương cốt và cốt tủy phá tổn rồi tái sinh mạnh mẽ hơn.","dacDiem":"Tiên khí phân giải thành vô số hạt giống giống bồ công anh và cắm rễ khắp thể phách.","congNang":["Giúp Tiên khí cắm rễ toàn diện trong ngũ tạng, xương cốt và cốt tủy.","Thúc đẩy thân thể tiến hóa, tẩy tủy và tiến tới Đại Niết bàn."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1430","tangDatToi":"Ba đạo Tiên khí cắm rễ toàn diện trong thể phách","trangThai":"đang tiến hóa"}],"trangThai":"đang tiến hóa","capNhatToi":"@c1430","tabs":{"tienTrinh":[{"chuong":"@c1430","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Tiên khí cắm rễ toàn diện","text":"Ba đạo Tiên khí của Thạch Hạo phân giải thành vô số hạt giống rồi dung nhập ngũ tạng, xương cốt và cốt tủy, đưa thể phách vào quá trình tiến hóa sâu.","anchor":"ba đạo Tiên khí phân giải, hóa thành lên tới hàng ngàn, hàng vạn bồ công anh bình thường hạt giống"}]},"nguon":["@c1430"]},{"id":"phap-mon-thai-than-the-dai-duoc","name":"Pháp môn thải thân thể đại dược","cn":"","loai":"luyen-the","loaiLabel":"Pháp môn luyện thể Tiên đạo","phamCap":"Không rõ","hePhai":"Tiên đạo","soHuu":["Thạch Hạo"],"blurb":"Pháp môn lấy chính thân thể làm nguồn dược, dùng xương làm lô, tiên vụ làm lửa và cốt tủy làm dược.","detail":"Thạch Hạo dùng pháp môn này luyện cốt tủy thành thân thể đại dược vượt quá cảnh giới hiện tại. Quá trình khiến toàn thân xương gãy, xương cũ bị đào thải rồi tái tạo, sau đó đẩy cựu huyết ra ngoài và sinh thành thần huyết mới để cải biến căn cơ.","thuocTinh":"Luyện thể, hoán cốt và thay máu","yeuCau":"Lấy xương, tiên vụ và cốt tủy của chính người tu luyện làm lô, lửa và dược.","uyLuc":"Có thể luyện đại dược tự thân để hoán cốt, thay máu và cải biến căn cơ.","dacDiem":"Đại dược phù hợp trực tiếp với bản thân người tu nhưng quá trình khiến toàn thân xương gãy và cựu huyết bị đào thải.","chieuTieuBieu":["Thải cốt tủy thành thân thể đại dược"],"trangThai":"Được Thạch Hạo thi triển thành công","capNhatToi":"@c1431","congNang":["Dùng đại dược luyện từ cốt tủy tự thân để hoán cốt, thay máu và cải mệnh."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1431","tangDatToi":"Thành công thải cốt tủy thành thân thể đại dược","trangThai":"Đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1431","loai":"thi triển","importance":"major","giaiDoan":"Luyện thành thân thể đại dược","text":"Thạch Hạo dùng hơn hai trăm khối xương làm thần lô, tiên vụ làm lửa và cốt tủy làm dược để hoàn thành quá trình hoán cốt, thay máu.","anchor":"Một khối cốt trở thành một lô thể, một thốc tiên vụ trở thành một đoàn hỏa"}]},"nguon":["@c1431"]},{"id":"loi-tri-hien-hoa-tu-mi-tam","name":"Lôi Trì hiển hóa từ mi tâm","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa xác định","hePhai":"Lôi đình","soHuu":["Thạch Hạo"],"blurb":"Thần thông hiển hóa Lôi Trì từ mi tâm để thu giữ và luyện diệt đối thủ.","detail":"Lôi Trì hóa thành một ao lớn cao trăm trượng, thu tám tu sĩ trẻ dị vực cùng binh khí vào trong. Sau khi thu nhỏ và chấn động, lôi đình bên trong tiêu diệt toàn bộ thân thể, thần hồn và binh khí của các mục tiêu.","thuocTinh":"Lôi đình","uyLuc":"Một lần thi triển đã tiêu diệt tám tu sĩ trẻ dị vực cùng binh khí.","dacDiem":"Có thể thu giữ nhiều mục tiêu trước khi dùng lôi đình luyện diệt.","chieuTieuBieu":"Hiển hóa Lôi Trì từ mi tâm","trangThai":"Đang được Thạch Hạo sử dụng","congNang":["Thu giữ đối thủ và binh khí vào trong Lôi Trì.","Dùng lôi đình chấn diệt thân thể, thần hồn và binh khí."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1432","tangDatToi":"Chưa xác định","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1432","tabs":{"tienTrinh":[{"chuong":"@c1432","loai":"thi triển","importance":"normal","giaiDoan":"Tiêu diệt nhóm truy sát","text":"Thạch Hạo hiển hóa Lôi Trì từ mi tâm, thu tám tu sĩ trẻ dị vực cùng binh khí rồi dùng lôi đình tiêu diệt toàn bộ.","anchor":"chiếc kia Lôi Trì thu nhỏ lại, mạnh mẽ chấn động"}]},"nguon":["@c1432"]},{"id":"than-niem-u-minh-cua-tang-si","name":"Thần niệm U Minh của táng sĩ","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thức","phamCap":"Không rõ","hePhai":"Táng sĩ","soHuu":["Táng sĩ cánh mục nát"],"blurb":"Một loại thần niệm mang U Minh Chi Lực, được táng sĩ dùng để truyền đạt ý niệm và tra hỏi nguồn gốc Đại La kiếm thai.","detail":"Táng sĩ phát ô quang từ mi tâm, tạo thành những gợn lan mờ để truyền thần niệm tới Thạch Hạo. Thần thức này thiếu sinh khí, xung đột với thần thức của người sống và có nguy cơ ăn mòn nguyên thần.","thuocTinh":"U Minh Chi Lực","yeuCau":"Do táng sĩ vận dụng","uyLuc":"Có thể xung đột với thần thức người sống và đe dọa ăn mòn nguyên thần.","dacDiem":"Thiếu sinh khí, mang tính chất âm u khác biệt với thần thức của sinh linh sống.","chieuTieuBieu":["Truyền thần niệm để tra hỏi nguồn gốc Đại La kiếm thai"],"congNang":["Truyền đạt ý niệm trực tiếp.","Dùng thần niệm để tra hỏi đối tượng.","Mang U Minh Chi Lực có thể ăn mòn nguyên thần người tiếp nhận."],"nguoiTu":[{"ten":"Táng sĩ cánh mục nát","tuChuong":"@c1434","tangDatToi":"Có thể truyền ý niệm qua thần thức","trangThai":"đang sử dụng"}],"trangThai":"Đang được táng sĩ sử dụng","capNhatToi":"@c1434","tabs":{"tienTrinh":[{"chuong":"@c1434","loai":"thi triển","importance":"normal","giaiDoan":"Dùng thần niệm tra hỏi","text":"Táng sĩ phát ô quang từ mi tâm và truyền thần niệm mang U Minh Chi Lực để hỏi Thạch Hạo vì sao Đại La kiếm thai nằm trong tay hắn.","anchor":"mi tâm ô quang nhấp nháy, khuếch tán ra đến, hình thành mông lung liên y"}]},"nguon":["@c1434"]},{"id":"cuu-nhan-than-thong","name":"Cửu nhãn thần thông","cn":"","aliases":["Chín ánh mắt thông"],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Cửu Mục Đạo Nhân"],"blurb":"Thần thông liên quan tới chín con mắt tại mi tâm của Cửu Mục Đạo Nhân.","detail":"Cửu Mục Đạo Nhân đã tu thành thần thông này và được mô tả là có pháp lực siêu tuyệt; tác dụng cụ thể chưa được hé lộ.","thuocTinh":"Nhãn thuật","uyLuc":"Người tu thành được mô tả có pháp lực siêu tuyệt.","nguoiTu":[{"ten":"Cửu Mục Đạo Nhân","tuChuong":"@c1435","tangDatToi":"Đã tu thành","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1435","loai":"có người đại thành","importance":"major","giaiDoan":"Đã tu thành","text":"Cửu Mục Đạo Nhân được xác nhận đã tu thành Cửu nhãn thần thông và có pháp lực siêu tuyệt.","anchor":"tu thành chín ánh mắt thông, pháp lực siêu tuyệt"}]},"capNhatToi":"@c1435","nguon":["@c1435"]},{"id":"tang-si-chi-nhan","name":"Táng sĩ chi nhãn","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Nhãn thuật","phamCap":"Không rõ","hePhai":"Táng sĩ","soHuu":["Táng sĩ cánh mục nát"],"blurb":"Nhãn thuật của táng sĩ dùng để nhận biết thật giả.","detail":"Táng sĩ sử dụng nhãn thuật này để nhận ra những lời Thạch Hạo dùng kích động mình chỉ có một nửa là thật.","thuocTinh":"Nhãn thuật","congNang":["Phân biệt thật giả trong lời nói."],"nguoiTu":[{"ten":"Táng sĩ cánh mục nát","tuChuong":"@c1435","tangDatToi":"Có thể vận dụng","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1435","loai":"thi triển","importance":"normal","giaiDoan":"Nhận biết thật giả","text":"Táng sĩ vận dụng táng sĩ chi nhãn để nhìn thấu lời kích động thật giả lẫn lộn của Thạch Hạo.","anchor":"Lời ngươi nói thật giả các một nửa, ta có táng sĩ chi nhãn."}]},"capNhatToi":"@c1435","nguon":["@c1435"]},{"id":"suc-dia-thanh-thon-than-thong","name":"Súc Địa Thành Thốn thần thông","cn":"","loai":"than-thong","loaiLabel":"Thần thông thân pháp","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Đội dò đường dị vực"],"blurb":"Thần thông thân pháp được tu sĩ dị vực vận dụng khi tháo chạy khỏi Thạch Hạo và táng sĩ.","detail":"Thuật giúp người thi triển độn hành với tốc độ rất nhanh, được nhiều thành viên đội dò đường đồng thời sử dụng trong lúc chạy trốn.","congNang":["Độn hành nhanh chóng để thoát khỏi truy sát."],"nguoiTu":[{"ten":"Đội dò đường dị vực","tuChuong":"@c1436","tangDatToi":"Không rõ","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1436","loai":"thi triển","importance":"normal","giaiDoan":"Đào thoát","text":"Đội dò đường dị vực thi triển thần thông này khi tháo chạy khỏi Thạch Hạo và táng sĩ.","anchor":"Trong lúc nhất thời, Súc Địa Thành Thốn thần thông, thiên nhai chỉ xích tổ thuật các loại..., cùng một chỗ thoáng hiện"}]},"capNhatToi":"@c1436","nguon":["@c1436"]},{"id":"thien-nhai-chi-xich-to-thuat","name":"Thiên nhai chỉ xích tổ thuật","cn":"","loai":"bi-thuat","loaiLabel":"Tổ thuật thân pháp","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Đội dò đường dị vực"],"blurb":"Tổ thuật thân pháp được đội dò đường dị vực thi triển để nhanh chóng thoát khỏi cuộc truy sát.","detail":"Thuật tác động lên khoảng cách, hỗ trợ người thi triển nhanh chóng kéo giãn cự ly với đối thủ trong lúc đào thoát.","congNang":["Rút ngắn khoảng cách di chuyển để nhanh chóng đào thoát."],"nguoiTu":[{"ten":"Đội dò đường dị vực","tuChuong":"@c1436","tangDatToi":"Không rõ","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1436","loai":"thi triển","importance":"normal","giaiDoan":"Đào thoát","text":"Đội dò đường dị vực đồng thời vận dụng tổ thuật này nhằm kéo giãn khoảng cách với những kẻ truy sát.","anchor":"Trong lúc nhất thời, Súc Địa Thành Thốn thần thông, thiên nhai chỉ xích tổ thuật các loại..., cùng một chỗ thoáng hiện"}]},"capNhatToi":"@c1436","nguon":["@c1436"]},{"id":"phap-tran-canh-gioi-trong-dia-quat","name":"Pháp trận cảnh giới trong địa quật","cn":"","loai":"khac","loaiLabel":"Trận pháp cảnh giới","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Đại tu sĩ Độn Nhất dị vực"],"blurb":"Pháp trận cảnh báo được đại tu sĩ Độn Nhất bố trí quanh nơi bế quan trong địa quật.","detail":"Đại tu sĩ thiết lập trận pháp vì lo Kim Ngưu hoặc sinh linh khác tới gần vào lúc mình đang đoạt tạo hóa. Khi Thạch Hạo giẫm lên trận văn, ánh sáng cảnh báo lập tức xuất hiện.","congNang":["Phát hiện và cảnh báo khi có sinh linh xâm nhập khu vực bế quan."],"nguoiTu":[{"ten":"Đại tu sĩ Độn Nhất dị vực","tuChuong":"@c1436","tangDatToi":"Có thể bố trí","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1436","loai":"xuất hiện","importance":"normal","giaiDoan":"Kích hoạt cảnh báo","text":"Trận pháp do đại tu sĩ Độn Nhất bố trí được kích hoạt khi Thạch Hạo giẫm lên trận văn.","anchor":"Độn một cảnh giới đại tu sĩ phi thường cẩn thận, bởi vì, hắn ở chỗ này bế quan, muốn đoạt tạo hóa, sợ chính mình tiến hành thời khắc mấu chốt, Kim Ngưu trở về, vì vậy thiết hạ đi một tí pháp trận."}]},"capNhatToi":"@c1436","nguon":["@c1436"]},{"id":"trang-vuc-giam-cam","name":"Tràng vực giam cầm","cn":"","loai":"than-thong","loaiLabel":"Tràng vực","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Đại tu sĩ Độn Nhất dị vực"],"blurb":"Tràng vực được đại tu sĩ Độn Nhất vận dụng để giam cầm khu vực quanh Thạch Hạo.","detail":"Khi rời hồ vàng truy bắt Thạch Hạo, đại tu sĩ triển khai tràng vực phong tỏa tám phương và ngăn chặn mọi đường chạy trốn.","congNang":["Giam cầm một khu vực, phong tỏa tám phương và chặn đường rút lui."],"nguoiTu":[{"ten":"Đại tu sĩ Độn Nhất dị vực","tuChuong":"@c1436","tangDatToi":"Không rõ","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1436","loai":"thi triển","importance":"normal","giaiDoan":"Phong tỏa địa quật","text":"Đại tu sĩ Độn Nhất triển khai tràng vực nhằm khóa chặt Thạch Hạo trong khu vực.","anchor":"Hắn vận dụng tràng vực, giam cầm phiến khu vực này, phong tỏa bát phương, ngăn chặn Thạch Hạo chạy trốn chi lộ."}]},"capNhatToi":"@c1436","nguon":["@c1436"]},{"id":"co-thuat-phong-thien-tuyet-dia-cua-tang-si","name":"Cổ thuật phong thiên tuyệt địa của Táng sĩ","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Cổ thuật","phamCap":"Không rõ","hePhai":"Táng sĩ","soHuu":["Táng sĩ cánh mục nát"],"blurb":"Cổ thuật dùng để phong tỏa thiên địa và cầm cố sinh linh trong một khu vực.","detail":"Táng sĩ vận dụng cổ thuật tại rừng rậm trong Thần Dược Sơn Mạch, khiến các sinh linh Dị Vực như mang gông xiềng và không thể đào thoát. Thạch Hạo là người duy nhất trong phạm vi không bị ảnh hưởng.","thuocTinh":"Tử khí và phong tỏa","uyLuc":"Có thể áp chế Cửu Mục đạo nhân cùng toàn bộ sinh linh Dị Vực tại chiến trường.","dacDiem":"Tạo trường vực phong thiên tuyệt địa, cầm cố mục tiêu trong phạm vi bao phủ.","congNang":["Phong tỏa thiên địa và cầm cố sinh linh trong khu vực tại @c1438."],"nguoiTu":[{"ten":"Táng sĩ cánh mục nát","tuChuong":"@c1438","tangDatToi":"Có thể áp chế toàn bộ lực lượng Dị Vực tại chiến trường","trangThai":"đang sử dụng"}],"trangThai":"Đang được Táng sĩ nắm giữ","capNhatToi":"@c1438","tabs":{"tienTrinh":[{"chuong":"@c1438","loai":"thi triển","importance":"normal","giaiDoan":"Phong tỏa chiến trường","text":"Táng sĩ thi triển cổ thuật để cầm cố Cửu Mục đạo nhân và toàn bộ sinh linh Dị Vực tại chỗ.","anchor":"ngoại trừ Thạch Hạo ở ngoài, tất cả mọi người cũng như cùng mang tới gông xiềng"}]},"nguon":["@c1438"]},{"id":"tran-dai-phuc-kich-cua-di-vuc","name":"Trận đài phục kích của dị vực","cn":"","aliases":[],"loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Các Chí Tôn dị vực"],"blurb":"Hệ thống trận đài được dị vực bố trí tại nhiều tiết điểm trọng yếu để phục kích lực lượng cứu viện từ Đế quan.","detail":"Mỗi trận đài do một Chí Tôn dị vực trực tiếp trấn giữ và chủ đạo. Toàn bộ bố trí nhằm chờ Mạnh Thiên Chính cùng các cường giả tối cao của Đế quan đến cứu Thạch Hạo rồi tiêu diệt một lượt.","thuocTinh":"Trận pháp phục kích","uyLuc":"Được chuẩn bị để đối phó các cường giả tối cao của Đế quan.","dacDiem":"Nhiều trận đài liên kết tại các tiết điểm trọng yếu và do Chí Tôn trực tiếp điều khiển.","congNang":["Phục kích và tiêu diệt các cường giả Đế quan đến cứu viện Thạch Hạo."],"nguoiTu":[{"ten":"Các Chí Tôn dị vực","tuChuong":"@c1439","tangDatToi":"Chủ trì trận đài","trangThai":"Đang vận hành"}],"trangThai":"Đang bố trí phục kích","capNhatToi":"@c1439","tabs":{"tienTrinh":[{"chuong":"@c1439","loai":"xuất hiện","importance":"normal","giaiDoan":"Bố trí phục kích","text":"Dị vực bố trí nhiều trận đài tại các tiết điểm trọng yếu, giao cho Chí Tôn trực tiếp chủ đạo để phục kích tầng cao Đế quan.","anchor":"Mỗi một chỗ tiết điểm đều là một tòa trận đài, do bọn họ tự mình chủ đạo"}]},"nguon":["@c1439"]},{"id":"thuat-dieu-dong-hai-cot-cua-tang-si","name":"Thuật điều động hài cốt của Táng Sĩ","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Táng Sĩ","soHuu":["Nữ Táng Sĩ"],"blurb":"Thần thông cho phép Táng Sĩ điều động di hài từ khoảng cách rất xa.","detail":"Nữ Táng Sĩ vận dụng nhánh táng khu dưới lòng đất để khiến vô số hài cốt ngoài đại mạc đứng dậy, ghép thành chữ và truyền thông điệp cảnh báo của Thạch Hạo.","congNang":["Điều khiển di hài từ xa và ghép chữ để truyền tin."],"nguoiTu":[{"ten":"Nữ Táng Sĩ","tuChuong":"@c1442","tangDatToi":"Có thể điều động hài cốt qua nhánh táng khu ở khoảng cách rất xa","trangThai":"thi-trien"}],"capNhatToi":"@c1442","tabs":{"tienTrinh":[{"chuong":"@c1442","loai":"thi triển","importance":"normal","giaiDoan":"Điều động hài cốt truyền tin","text":"Nữ Táng Sĩ điều khiển hài cốt ngoài đại mạc đứng dậy và ghép thành thông điệp cảnh báo Đế quan.","anchor":"Táng Sĩ bản lĩnh vô cùng kỳ dị, có thể chưởng khống thi thụ, có thể điều động di hài, dù cho cách rất xa, như thế hữu hiệu."}]},"nguon":["@c1442"]},{"id":"tuyet-the-dai-tran-ngoai-than-duoc-son-mach","name":"Tuyệt thế đại trận ngoài Thần Dược Sơn Mạch","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Dị vực","soHuu":["Dị vực"],"blurb":"Đại trận do dị vực bố trí ngoài Thần Dược Sơn Mạch để phối hợp với Chí Tôn mai phục.","detail":"Trận pháp được đặt ngoài sơn mạch nhằm phục kích và ngăn lực lượng Đế quan tiến vào cứu Thạch Hạo.","nguonGoc":"Do dị vực bố trí ngoài Thần Dược Sơn Mạch.","congNang":["Phối hợp với Chí Tôn dị vực phục kích lực lượng cứu viện từ Đế quan."],"capNhatToi":"@c1442","tabs":{"tienTrinh":[{"chuong":"@c1442","loai":"xuất hiện","importance":"normal","giaiDoan":"Bố trí phục kích","text":"Dị vực bố trí tuyệt thế đại trận ngoài Thần Dược Sơn Mạch để chờ lực lượng Đế quan tới cứu viện.","anchor":"khẳng định có như vậy lão tổ ở sơn ở ngoài, tuyệt rơi xuống tuyệt thế đại trận."}]},"nguon":["@c1442"]},{"id":"xong-luan-hoi","name":"Xông Luân Hồi","cn":"","aliases":[],"loai":"khac","loaiLabel":"Pháp môn hoặc hành trình luân hồi","phamCap":"Không rõ","hePhai":"Luân hồi","soHuu":["Tào Vũ Sinh"],"blurb":"Phương thức hoặc hành trình để ý chí trải qua nhiều đời chinh chiến. Tào Vũ Sinh nói ý chí của mình đã xông qua chín đời, mười đời hoặc nhiều hơn.","detail":"Xông Luân Hồi khiến ý chí của Tào Vũ Sinh chinh chiến qua nhiều thế, nhờ đó ông chứng kiến một góc của thời kỳ hắc ám và những năm tháng mà người ngoài khó tưởng tượng.","thuocTinh":"Luân hồi nhiều đời","yeuCau":"Không rõ","uyLuc":"Đưa ý chí trải qua nhiều đời chinh chiến và tiếp xúc với những thời đại xa xưa.","dacDiem":"Người trải qua vừa có liên hệ với người xưa, vừa không hoàn toàn là người xưa.","congNang":["Đưa ý chí chinh chiến qua chín đời, mười đời hoặc nhiều hơn."],"nguoiTu":[{"ten":"Tào Vũ Sinh","tuChuong":"@c1444","tangDatToi":"Không rõ","trangThai":"Đã trải qua nhiều đời"}],"trangThai":"Đang được Tào Vũ Sinh trải nghiệm","capNhatToi":"@c1444","tabs":{"tienTrinh":[{"chuong":"@c1444","loai":"xuất hiện","importance":"normal","giaiDoan":"Chinh chiến nhiều đời","text":"Tào Vũ Sinh tiết lộ ý chí của mình vẫn đang xông Luân Hồi và đã chinh chiến qua chín đời, mười đời hoặc nhiều hơn.","anchor":"Trên thực tế, ta vẫn ở xông Luân Hồi, ý chí của ta chinh chiến cửu thế, mười đời, vẫn là càng nhiều?"}]},"nguon":["@c1444"]},{"id":"chin-dao-luan-hoi-dau-an","name":"Chín đạo Luân Hồi dấu ấn","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Pháp môn Luân Hồi","phamCap":"Không rõ","hePhai":"Luân Hồi","soHuu":["Tào Vũ Sinh"],"blurb":"Pháp môn được Tào Vũ Sinh tu thành qua chín đời chôn cất và thi biến, giúp hắn nhớ lại quá khứ và duy trì sự liên tục của bản thân.","detail":"Tào Vũ Sinh khẳng định mình không chỉ trải qua thi biến đơn thuần. Chín đạo Luân Hồi dấu ấn giúp hắn khôi phục ký ức của những đời trước và xác nhận người ở hậu thế vẫn là chính mình.","thuocTinh":"Luân Hồi và ký ức","yeuCau":"Trải qua chín đời chôn cất và thi biến","dacDiem":"Gắn ký ức qua chín đời, giúp người tu nhớ lại quá khứ sau nhiều lần thân thể và linh thức biến đổi.","congNang":["Giữ và khôi phục ký ức qua chín đời chôn cất và thi biến tại @c1445."],"nguoiTu":[{"ten":"Tào Vũ Sinh","tuChuong":"@c1445","tangDatToi":"Chín dấu ấn","trangThai":"Đã tu thành"}],"trangThai":"Đã tu thành","capNhatToi":"@c1445","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1445","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Chín dấu ấn","text":"Tào Vũ Sinh tiết lộ rằng hắn đã tu thành chín đạo Luân Hồi dấu ấn, nhờ đó nhớ lại quá khứ và vẫn giữ được bản thân sau chín đời.","anchor":"ta tu ra chín đạo Luân Hồi dấu ấn, thật sự nhớ tới đi qua"}]},"nguon":["@c1445"]},{"id":"do-kiep-tien-cong","name":"Độ kiếp tiên công","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Tiên công","phamCap":"Không rõ","hePhai":"Độ kiếp","soHuu":["Tào Vũ Sinh"],"blurb":"Tiên công được Tào Vũ Sinh dùng để gây dựng lại thân thể sau khi bị thiên phạt đánh chia năm xẻ bảy.","detail":"Khi Tào Vũ Sinh cố tiết lộ tin tức từ hậu thế, lôi đình xuyên thủng và đánh tan thân thể hắn. Độ kiếp tiên công giúp hắn tái lập cơ thể và sống sót sau đòn trừng phạt.","thuocTinh":"Độ kiếp và tái tạo thân thể","uyLuc":"Giúp Tào Vũ Sinh gây dựng lại thân thể sau khi bị thiên phạt xuyên cổ kim đánh tan.","dacDiem":"Được thi triển trong lúc người dùng chịu sức trừng phạt của thiên uy.","congNang":["Gây dựng lại thân thể sau khi bị thiên phạt đánh chia năm xẻ bảy tại @c1445."],"nguoiTu":[{"ten":"Tào Vũ Sinh","tuChuong":"@c1445","tangDatToi":"Có thể tái tạo thân thể","trangThai":"Đang sử dụng"}],"trangThai":"Đang lưu truyền","capNhatToi":"@c1445","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1445","loai":"thi triển","importance":"normal","giaiDoan":"Tái tạo thân thể","text":"Tào Vũ Sinh thi triển Độ kiếp tiên công để gây dựng lại thân thể sau khi bị thiên phạt đánh tan.","anchor":"Cuối cùng, hắn gây dựng lại thân thể, không có bị đánh giết"}]},"nguon":["@c1445"]},{"id":"vo-thuong-cong-phap-cua-tao-vu-sinh","name":"Vô thượng công pháp của Tào Vũ Sinh","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Vô thượng","hePhai":"Đạo gia","soHuu":["Tào Vũ Sinh"],"blurb":"Công pháp do Tào Vũ Sinh khai sáng, có thể điều động chớp giật và giúp hắn chống lại Tiên Đạo lôi đình.","detail":"Khi Tào Vũ Sinh bị Tiên Đạo lôi đình trói buộc vì cố truyền tin xuyên thời gian, công pháp này giúp hắn điều động chớp giật và tránh lập tức hình thần câu diệt.","thuocTinh":"Lôi đình","nguonGoc":"Do Tào Vũ Sinh khai sáng","uyLuc":"Giúp Tào Vũ Sinh cầm cự trong Tiên Đạo lôi đình thay vì lập tức hình thần câu diệt.","dacDiem":"Có thể điều động chớp giật để chống lại lôi đình.","congNang":["Điều động chớp giật và chống lại lôi đình."],"nguoiTu":[{"ten":"Tào Vũ Sinh","tuChuong":"@c1446","tangDatToi":"Người khai sáng","trangThai":"Đang sử dụng"}],"trangThai":"Đang lưu truyền qua người khai sáng","capNhatToi":"@c1446","tabs":{"tienTrinh":[{"chuong":"@c1446","loai":"thi triển","importance":"normal","giaiDoan":"Chống Tiên Đạo lôi đình","text":"Tào Vũ Sinh vận dụng công pháp do mình khai sáng để điều động chớp giật, nhờ đó không lập tức hình thần câu diệt dưới Tiên Đạo lôi đình.","anchor":"thế nhưng hắn từng khai sáng có vô thượng công pháp, có thể điều động chớp giật các loại, không có lập tức hình thần đều diệt."}]},"nguon":["@c1446"]},{"id":"vo-uy-su-tu-hong","name":"Vô Úy Sư Tử hống","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Trấn giáo thần thông","hePhai":"Vô Úy Sư Tử nhất tộc","soHuu":["Sư tử vàng không thuần huyết","Ba sư tử vàng thuộc mạch Vô Úy Sư Tử"],"blurb":"Trấn giáo thần thông của Vô Úy Sư Tử nhất tộc, dùng tiếng rống để phát động công kích.","detail":"Ba Hoàng Kim sư tử đồng thời thi triển thần thông này để đánh lén Thạch Hạo sau khi con tù binh phá phong ấn, nhưng đòn đánh không thể xoay chuyển cục diện.","thuocTinh":"Âm thanh công kích","uyLuc":"Đòn hợp kích của ba Hoàng Kim sư tử chỉ khiến ngón tay Thạch Hạo hơi tê.","dacDiem":"Được xác định là một trong các trấn giáo thần thông của tộc Vô Úy Sư Tử.","chieuTieuBieu":["Vô Úy Sư Tử hống"],"congNang":["Phát động công kích bằng tiếng rống."],"nguoiTu":[{"ten":"Sư tử vàng không thuần huyết","tuChuong":"@c1450","tangDatToi":"Có thể thi triển","trangThai":"tu-vong"},{"ten":"Ba sư tử vàng thuộc mạch Vô Úy Sư Tử","tuChuong":"@c1450","tangDatToi":"Có thể phối hợp thi triển","trangThai":"tu-vong"}],"trangThai":"Còn truyền thừa trong Vô Úy Sư Tử nhất tộc","capNhatToi":"@c1450","tabs":{"tienTrinh":[{"chuong":"@c1450","loai":"thi triển","importance":"normal","giaiDoan":"Ba Hoàng Kim sư tử hợp kích","text":"Ba Hoàng Kim sư tử đồng thời dùng Vô Úy Sư Tử hống để đánh lén Thạch Hạo nhưng không thể gây thương tích đáng kể.","anchor":"chính là tộc này trấn giáo thần thông chi — —— Vô Úy Sư Tử hống"}]},"nguon":["@c1450"]},{"id":"phuong-phap-pha-giai-ach-tho-cua-di-vuc","name":"Phương pháp phá giải ách thổ của dị vực","cn":"","loai":"bi-thuat","loaiLabel":"Phương pháp phá giải","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"blurb":"Phương pháp do Du Đà và các tồn tại dị vực truyền cho Đại nhân trẻ tuổi Đế Tộc nhằm phá giải những trở ngại tại ách thổ.","detail":"Phương pháp này được phối hợp với nhiều bí khí và hậu chiêu để mở nơi cất chiếc rương gỗ cổ. Nội dung vận hành cụ thể chưa được hé lộ.","nguonGoc":"Do Du Đà và các Bất Hủ chi Vương dị vực truyền lại.","thuocTinh":"Phá giải cấm chế tại ách thổ","trangThai":"Được đoàn dị vực sử dụng","nguoiTu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1452","tangDatToi":"Mang theo phương pháp phá giải","trangThai":"Đang sử dụng"}],"congNang":["Phối hợp với bí khí và các phương tiện khác để mở nơi cất chiếc rương gỗ cổ."],"tabs":{"tienTrinh":[{"chuong":"@c1452","loai":"xuất hiện","importance":"normal","giaiDoan":"Được dùng trong kế hoạch mở mộ","text":"Du Đà và các tồn tại dị vực truyền phương pháp phá giải cho Đại nhân trẻ tuổi Đế Tộc để phục vụ kế hoạch khiến chiếc rương xuất thế.","anchor":"Vì này một lần thành công, Du Đà các loại (chờ) từng ban tặng bí khí, báo cho Đế Tộc vị này tuổi trẻ đại nhân phương pháp phá giải"}]},"capNhatToi":"@c1452","nguon":["@c1452"]},{"id":"chan-kinh-trieu-hoan-bat-hu-chi-vuong","name":"Chân kinh triệu hoán Bất Hủ Chi Vương","cn":"","loai":"bi-thuat","loaiLabel":"Triệu hoán kinh","phamCap":"Bất Hủ Chi Vương","hePhai":"Dị vực","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"blurb":"Kinh văn dùng Du Đà chân huyết làm môi giới để dẫn pháp thể mạnh nhất của Du Đà vượt qua Thiên Uyên.","detail":"Kinh văn được ghi bằng đại đạo văn tự trên một tấm da thú. Khi tấm da thấm Du Đà chân huyết và tự cháy, tiếng tụng đầy đủ danh hiệu Du Đà vang lên, phối hợp với cốt đài để mở cửa triệu hoán.","thuocTinh":"Triệu hoán","nguonGoc":"Do Bất Hủ Chi Vương chuẩn bị","uyLuc":"Có thể dẫn pháp thể mạnh nhất của Du Đà vượt qua Thiên Uyên trong thời gian ngắn.","dacDiem":"Cần phối hợp với Du Đà chân huyết, vật dẫn kinh văn và Cốt đài triệu hoán.","chieuTieuBieu":["Triệu gọi pháp thể Bất Hủ Chi Vương xuyên qua Thiên Uyên"],"congNang":["Dẫn pháp thể mạnh nhất của Du Đà vượt qua Thiên Uyên."],"nguoiTu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1453","tangDatToi":"Có thể kích hoạt nghi thức khi đủ vật dẫn","trangThai":"đã thi triển"}],"trangThai":"Đã được kích hoạt","capNhatToi":"@c1453","tabs":{"tienTrinh":[{"chuong":"@c1453","loai":"thi triển","importance":"major","giaiDoan":"Kích hoạt triệu hoán","text":"Tấm da thú thấm Du Đà chân huyết rồi tự cháy, phát ra tiếng tụng kinh để dẫn pháp thể Du Đà vượt qua Thiên Uyên.","anchor":"Đây là một mảnh kinh văn, là triệu hoán Bất Hủ chi Vương đại đạo văn tự, lúc này phát sinh đinh tai nhức óc tiếng tụng kinh, mấy lần nhắc tới Du Đà tên đầy đủ!"}]},"nguon":["@c1453"]},{"id":"to-thuat-cua-du-da","name":"Tổ thuật của Du Đà","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Dị Vực","soHuu":["Du Đà"],"blurb":"Tổ thuật được Du Đà vận dụng khi bàn tay pháp thể của hắn bị Táng sĩ chặn đường.","detail":"Thuật khiến cánh tay Du Đà phát sáng, giúp hắn đối kháng lực lượng của bàn tay Táng sĩ trong lúc mang Nát rương gỗ rút lui.","thuocTinh":"Đối kháng","uyLuc":"Có thể giúp bộ phận pháp thể của Du Đà ngạnh kháng bàn tay Táng sĩ.","congNang":["Khiến cánh tay phát sáng để đối kháng lực lượng của Táng sĩ tại @c1454."],"nguoiTu":[{"ten":"Du Đà","tuChuong":"@c1454","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1454","loai":"thi triển","importance":"normal","giaiDoan":"Đối kháng Táng sĩ","text":"Du Đà vận dụng Tổ thuật làm cánh tay phát sáng để đối kháng bàn tay Táng sĩ trong lúc rút lui cùng Nát rương gỗ.","anchor":"Du Đà cánh tay phát quang, lấy mạc danh Tổ thuật đối kháng"}]},"capNhatToi":"@c1454","nguon":["@c1454"]},{"id":"phap-an-cua-tang-vuong","name":"Pháp ấn của Táng Vương","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Táng Vương","soHuu":["Táng Vương"],"blurb":"Pháp ấn được Táng Vương dùng để đối đầu trực diện với hoàng kim trường thương của An Lan.","detail":"Táng Vương liên tiếp kết pháp ấn ép về phía An Lan. Va chạm giữa pháp ấn và hoàng kim trường thương khiến khu vực chiến trường hóa thành hỗn độn.","thuocTinh":"Đạo tắc và pháp ấn","uyLuc":"Có thể đối kháng hoàng kim trường thương của An Lan và khiến chiến trường hóa thành hỗn độn.","congNang":["Đối kháng trực diện hoàng kim trường thương của An Lan."],"nguoiTu":[{"ten":"Táng Vương","tuChuong":"@c1455","tangDatToi":"","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1455","loai":"thi triển","importance":"normal","giaiDoan":"Đối đầu An Lan","text":"Táng Vương kết pháp ấn va chạm trực diện với hoàng kim trường thương, khiến khu vực giao tranh hóa thành hỗn độn.","anchor":"Táng Vương cái thế pháp ấn đánh vào hoàng kim trường thương trên"}]},"capNhatToi":"@c1455","nguon":["@c1455"]},{"id":"dau-an-thoi-gian-cua-du-da","name":"Dấu ấn thời gian của Du Đà","cn":"","loai":"than-thong","loaiLabel":"Thần thông thời gian","phamCap":"","hePhai":"Du Đà","soHuu":["Du Đà"],"blurb":"Dấu ấn do Du Đà lưu lại trong thời gian, có thể tái hiện một đòn đánh vào thời điểm thích hợp.","detail":"Dấu ấn hiện thành bàn tay Du Đà phía sau Táng Vương và bất ngờ đánh trúng đối phương. Sức ảnh hưởng chỉ kéo dài trong khoảnh khắc rồi tan biến.","thuocTinh":"Thời gian","uyLuc":"Có thể tái hiện một đòn đánh của Du Đà từ dấu vết lưu trong dòng sông năm tháng.","dacDiem":"Chỉ ảnh hưởng trong một khoảnh khắc sau khi tái hiện.","congNang":["Tái hiện một đòn đánh từ dấu vết được lưu lại trong thời gian."],"nguoiTu":[{"ten":"Du Đà","tuChuong":"@c1455","tangDatToi":"","trangThai":"đã lưu dấu"}],"tabs":{"tienTrinh":[{"chuong":"@c1455","loai":"thi triển","importance":"normal","giaiDoan":"Tập kích Táng Vương","text":"Dấu ấn thời gian của Du Đà tái hiện thành một bàn tay, đánh trúng Táng Vương rồi nhanh chóng biến mất.","anchor":"đó là hắn lưu lại thời gian dấu ấn"}]},"capNhatToi":"@c1455","nguon":["@c1455"]},{"id":"thoi-gian-chi-mau-va-khong-gian-chi-mau","name":"Thời gian chi mâu và Không gian chi mâu","cn":"","loai":"than-thong","loaiLabel":"Đại đạo thần tắc","phamCap":"","hePhai":"Cô Tộc","soHuu":["Chí tôn trẻ tuổi Cô Tộc"],"blurb":"Hai trường mâu do đại đạo thời gian và không gian biến thành, được truyền nhân Cô Tộc sử dụng trong cuộc tranh đoạt nát rương gỗ.","detail":"Thời gian chi mâu có thể khiến thời gian hỗn loạn như đình chỉ, còn Không gian chi mâu xuyên phá vật cản và ép Trường Sinh Tiên thụ ra khỏi hư không.","thuocTinh":"Thời gian và không gian","uyLuc":"Hai trường mâu mang hơi thở khủng bố, có thể làm rối loạn thời gian và phá hư không.","dacDiem":"Gồm hai trường mâu do đại đạo thần tắc biến thành.","congNang":["Làm rối loạn thời gian và tạo cảm giác thời gian đình chỉ.","Xuyên phá vật cản, phá hư không và ép mục tiêu đang ẩn trong hư không hiện ra."],"nguoiTu":[{"ten":"Chí tôn trẻ tuổi Cô Tộc","tuChuong":"@c1457","tangDatToi":"","trangThai":"thi triển"}],"trangThai":"đang được sử dụng","capNhatToi":"@c1457","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1457","loai":"thi triển","importance":"normal","giaiDoan":"Song mâu đại đạo","text":"Truyền nhân Cô Tộc hóa đại đạo thời gian và không gian thành hai trường mâu để tấn công Thạch Hạo, sau đó dùng Không gian chi mâu ép Trường Sinh Tiên thụ hiện ra khỏi hư không.","anchor":"Bởi vì, cái kia hai thanh trường thương đều là đại đạo thần tắc biến thành, ẩn chứa hơi thở cực kỳ khủng bố."}]},"nguon":["@c1457"]},{"id":"hu-khong-lien-y","name":"Hư không liên y","cn":"","loai":"bi-thuat","loaiLabel":"Thiên phú bí pháp không gian","phamCap":"Không rõ","hePhai":"Cô Tộc","soHuu":["Chí tôn trẻ tuổi Cô Tộc"],"blurb":"Bí pháp khiến thập phương hư không cộng hưởng và phát ra những gợn sóng thần quang. Người thi triển dùng các gợn sóng ấy để cảm ứng sinh linh và xác định phương vị mục tiêu.","detail":"Truyền nhân Cô Tộc thi triển Hư không liên y để tìm lại Trường Sinh thụ sau khi mục tiêu độn sâu dưới lòng đất.","thuocTinh":"Không gian","congNang":["Dò tìm sinh linh thông qua gợn sóng lan truyền trong hư không @c1458"],"nguoiTu":[{"ten":"Chí tôn trẻ tuổi Cô Tộc","tuChuong":"@c1458","tangDatToi":"Đã thi triển","trangThai":"đang tu"}],"trangThai":"đang lưu truyền","capNhatToi":"@c1458","tabs":{"tienTrinh":[{"chuong":"@c1458","loai":"thi triển","importance":"normal","giaiDoan":"Dò tìm Trường Sinh thụ","text":"Truyền nhân Cô Tộc tạo gợn sóng thần quang lan khắp hư không để cảm ứng và xác định vị trí Trường Sinh thụ.","anchor":"có thần quang hóa thành liên y gợn sóng, hướng về khắp nơi khuếch tán"}]},"nguon":["@c1458"]},{"id":"chuong-trung-tang-quoc","name":"Chưởng Trung Tăng Quốc","cn":"","loai":"than-thong","loaiLabel":"Thần thông cổ tăng","phamCap":"Không rõ","hePhai":"Cổ tăng nhất mạch","soHuu":["Vô Úy Sư Tử"],"blurb":"Thần thông hóa lòng bàn tay thành một thế giới để giữ và luyện hóa mục tiêu. Vô Úy Sư Tử dùng thuật này đối phó Thạch Hạo nhưng bị Đại La kiếm thai chém mở.","detail":"Chưởng Trung Tăng Quốc có nguồn gốc từ Cổ tăng nhất mạch. Thế giới trong lòng bàn tay cần khép kín để giam giữ mục tiêu, nhưng lần thi triển tại chi mạch táng địa đã bị phá trước khi hoàn thành.","nguonGoc":"Cổ tăng nhất mạch","congNang":["Hóa lòng bàn tay thành thế giới để giam giữ và luyện hóa mục tiêu @c1458"],"nguoiTu":[{"ten":"Vô Úy Sư Tử","tuChuong":"@c1458","tangDatToi":"Đã thi triển","trangThai":"đang tu"}],"trangThai":"đang lưu truyền","capNhatToi":"@c1458","tabs":{"tienTrinh":[{"chuong":"@c1458","loai":"thi triển","importance":"normal","giaiDoan":"Giam giữ Thạch Hạo","text":"Vô Úy Sư Tử hóa lòng bàn tay thành một thế giới nhằm giữ và luyện hóa Thạch Hạo, nhưng thế giới bị Đại La kiếm thai chém mở.","anchor":"hóa thành một thế giới, muốn lưu lại Thạch Hạo, đem luyện hóa đi"}]},"nguon":["@c1458"]},{"id":"bat-diet-kinh-van-tren-kiem-thai","name":"Bất Diệt Kinh văn trên kiếm thai","cn":"","loai":"khac","loaiLabel":"Kinh văn hiện hình","phamCap":"Không rõ","hePhai":"Bất Diệt Kinh","soHuu":["Thạch Hạo"],"blurb":"Kinh văn óng ánh hiện lên trên Đại La kiếm thai khi Thạch Hạo chống đòn. Hiện tượng này đi cùng nhát chém đánh bật trường mâu của truyền nhân Cô Tộc.","detail":"Khi Thạch Hạo trở tay chém trường mâu đang tập kích từ phía sau, Bất Diệt Kinh văn hiện rõ trên kiếm thai và tỏa ánh sáng khiếp người.","congNang":["Hiện trên Đại La kiếm thai khi Thạch Hạo chống trường mâu @c1458"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1458","tangDatToi":"Kinh văn hiện trên kiếm thai","trangThai":"đang sử dụng"}],"trangThai":"đã hiện hình","capNhatToi":"@c1458","tabs":{"tienTrinh":[{"chuong":"@c1458","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện trên kiếm thai","text":"Bất Diệt Kinh văn óng ánh hiện lên trên Đại La kiếm thai khi Thạch Hạo chém bật trường mâu của truyền nhân Cô Tộc.","anchor":"kiếm thai nổi lên hiện Bất Diệt Kinh văn, óng ánh mà khiếp người"}]},"nguon":["@c1458"]}]};
